        private static bool HasCjk(string s)
        {
            if (string.IsNullOrEmpty(s)) return false;
            for (int i = 0; i < s.Length; i++)
            {
                if (s[i] >= 0x4E00 && s[i] <= 0x9FFF) return true;
            }
            return false;
        }

        public static string Translate(string raw)
        {
            if (!Enabled || string.IsNullOrEmpty(raw))
                return raw;

            if (raw.Length > 2048)
                return raw;

            if (_cache.TryGetValue(raw, out string cached))
                return cached;

            string result = TranslateInternal(raw);
            if (_cache.Count < 16384)
                _cache[raw] = result;
            return result;
        }

        private static string TranslateInternal(string raw)
        {
            string trimmed = raw.Trim();
            if (string.IsNullOrEmpty(trimmed))
                return raw;

            if (ExactDict.TryGetValue(trimmed, out string exactHit))
            {
                if (raw.Length == trimmed.Length) return exactHit;
                return raw.Replace(trimmed, exactHit);
            }

            if (HasCjk(trimmed))
            {
                return FixMixedCjkSentence(trimmed);
            }

            if (trimmed.Length > 4 && trimmed[1] == ' ' && trimmed[2] == '-' && trimmed[3] == ' ' && char.IsLetterOrDigit(trimmed[0]))
            {
                string prefix = trimmed.Substring(0, 4);
                string rest = trimmed.Substring(4);
                return prefix + TranslateInternal(rest);
            }

            int colonIdx = trimmed.IndexOf(": ", StringComparison.Ordinal);
            if (colonIdx > 0 && colonIdx < trimmed.Length - 2)
            {
                string left = trimmed.Substring(0, colonIdx).Trim();
                string right = trimmed.Substring(colonIdx + 2).Trim();
                if (ExactDict.TryGetValue(left, out string zhLeft))
                {
                    string zhRight = ExactDict.TryGetValue(right, out string rHit) ? rHit : TranslateNounPhrase(right);
                    return $"{zhLeft}：{zhRight}";
                }
            }

            string combatTranslated = TryTranslateCombatSentence(trimmed);
            if (combatTranslated != null)
                return combatTranslated;

            string nounTranslated = TranslateNounPhrase(trimmed);
            if (nounTranslated != trimmed)
                return nounTranslated;

            return raw;
        }

        private static string FixMixedCjkSentence(string s)
        {
            if (s.StartsWith("You feel ", StringComparison.Ordinal)) s = "你感到" + s.Substring(9);
            else if (s.StartsWith("You hear ", StringComparison.Ordinal)) s = "你听到" + s.Substring(9);
            else if (s.StartsWith("You can't ", StringComparison.Ordinal)) s = "你无法" + s.Substring(10);
            else if (s.StartsWith("You see ", StringComparison.Ordinal)) s = "你看到" + s.Substring(8);
            else if (s.StartsWith("Your ", StringComparison.Ordinal)) s = "你的" + s.Substring(5);
            else if (s.StartsWith("You ", StringComparison.Ordinal)) s = "你" + s.Substring(4);
            else if (s.StartsWith("There ", StringComparison.Ordinal)) s = s.Substring(6);
            else if (s.StartsWith("The ", StringComparison.Ordinal)) s = s.Substring(4);

            return Regex.Replace(s, @"[A-Za-z][A-Za-z0-9\s\+\-'\(\),]*[A-Za-z0-9\)]", m =>
            {
                string span = m.Value.Trim();
                if (string.IsNullOrEmpty(span)) return m.Value;
                if (ExactDict.TryGetValue(span, out string hit)) return hit;
                if (CombatVerbDict.TryGetValue(span, out string vHit)) return vHit;
                string np = TranslateNounPhrase(span);
                return np != span ? np : m.Value;
            });
        }

        private static string TryTranslateCombatSentence(string s)
        {
            char endPunct = '.';
            string core = s;
            if (core.EndsWith("!") || core.EndsWith("."))
            {
                endPunct = core[core.Length - 1];
                core = core.Substring(0, core.Length - 1).Trim();
            }
            string zhPunct = endPunct == '!' ? "！" : "。";

            if (core.EndsWith(" is killed", StringComparison.OrdinalIgnoreCase))
            {
                string subj = TranslateNounPhrase(core.Substring(0, core.Length - 10).Trim());
                return $"{subj}被杀死了{zhPunct}";
            }
            if (core.EndsWith(" is destroyed", StringComparison.OrdinalIgnoreCase))
            {
                string subj = TranslateNounPhrase(core.Substring(0, core.Length - 13).Trim());
                return $"{subj}被摧毁了{zhPunct}";
            }
            if (core.StartsWith("You kill ", StringComparison.OrdinalIgnoreCase))
            {
                string obj = TranslateNounPhrase(core.Substring(9).Trim());
                return $"你杀死了{obj}{zhPunct}";
            }
            if (core.StartsWith("You destroy ", StringComparison.OrdinalIgnoreCase))
            {
                string obj = TranslateNounPhrase(core.Substring(12).Trim());
                return $"你摧毁了{obj}{zhPunct}";
            }

            foreach (var kv in CombatVerbDict)
            {
                string token = " " + kv.Key + " ";
                int idx = core.IndexOf(token, StringComparison.OrdinalIgnoreCase);
                if (idx > 0)
                {
                    string subjRaw = core.Substring(0, idx).Trim();
                    string objRaw = core.Substring(idx + token.Length).Trim();
                    string subjZh = subjRaw.Equals("You", StringComparison.OrdinalIgnoreCase) ? "你" : TranslateNounPhrase(subjRaw);
                    string objZh = objRaw.Equals("you", StringComparison.OrdinalIgnoreCase) ? "你" :
                                   objRaw.Equals("itself", StringComparison.OrdinalIgnoreCase) ? "它自己" :
                                   TranslateNounPhrase(objRaw);
                    if (subjZh != subjRaw || objZh != objRaw || subjRaw.Equals("You", StringComparison.OrdinalIgnoreCase) || objRaw.Equals("you", StringComparison.OrdinalIgnoreCase))
                    {
                        return $"{subjZh}{kv.Value}{objZh}{zhPunct}";
                    }
                }
            }
            return null;
        }

        public static string TranslateNounPhrase(string phrase)
        {
            if (string.IsNullOrEmpty(phrase)) return phrase;
            string work = phrase.Trim();

            if (ExactDict.TryGetValue(work, out string direct))
                return direct;

            string trailingZh = "";
            bool foundTag = true;
            while (foundTag)
            {
                foundTag = false;
                foreach (var (enSuf, zhSuf) in _trailingTags)
                {
                    if (work.EndsWith(enSuf, StringComparison.OrdinalIgnoreCase))
                    {
                        trailingZh = zhSuf + trailingZh;
                        work = work.Substring(0, work.Length - enSuf.Length).TrimEnd();
                        foundTag = true;
                        break;
                    }
                }
                if (!foundTag)
                {
                    var unpaidMatch = Regex.Match(work, @"\s*\(unpaid,\s*(\d+)\s*zorkmids?\)$", RegexOptions.IgnoreCase);
                    if (unpaidMatch.Success)
                    {
                        trailingZh = $"（未付账，{unpaidMatch.Groups[1].Value} 枚金币）" + trailingZh;
                        work = work.Substring(0, unpaidMatch.Index).TrimEnd();
                        foundTag = true;
                    }
                    else
                    {
                        var chargeMatch = Regex.Match(work, @"\s*\(\d+:\d+\)$");
                        if (chargeMatch.Success)
                        {
                            trailingZh = " " + chargeMatch.Value.Trim() + trailingZh;
                            work = work.Substring(0, chargeMatch.Index).TrimEnd();
                            foundTag = true;
                        }
                    }
                }
            }

            string leadZh = "";
            var numMatch = Regex.Match(work, @"^(\d+)\s+(.*)$");
            if (numMatch.Success)
            {
                leadZh = numMatch.Groups[1].Value + " ";
                work = numMatch.Groups[2].Value.TrimStart();
            }
            else if (work.StartsWith("your ", StringComparison.OrdinalIgnoreCase))
            {
                leadZh = "你的";
                work = work.Substring(5).TrimStart();
            }
            else if (work.StartsWith("some ", StringComparison.OrdinalIgnoreCase))
            {
                leadZh = "一些";
                work = work.Substring(5).TrimStart();
            }
            else if (work.StartsWith("no ", StringComparison.OrdinalIgnoreCase))
            {
                leadZh = "没有";
                work = work.Substring(3).TrimStart();
            }
            else if (work.StartsWith("an ", StringComparison.OrdinalIgnoreCase))
            {
                work = work.Substring(3).TrimStart();
            }
            else if (work.StartsWith("a ", StringComparison.OrdinalIgnoreCase))
            {
                work = work.Substring(2).TrimStart();
            }
            else if (work.StartsWith("the ", StringComparison.OrdinalIgnoreCase))
            {
                work = work.Substring(4).TrimStart();
            }

            string modsZh = "";
            bool matchedMod = true;
            while (matchedMod && !string.IsNullOrEmpty(work))
            {
                matchedMod = false;
                var enchMatch = Regex.Match(work, @"^([\+\-]\d+)\s+(.*)$");
                if (enchMatch.Success)
                {
                    modsZh += enchMatch.Groups[1].Value + " ";
                    work = enchMatch.Groups[2].Value.TrimStart();
                    matchedMod = true;
                    continue;
                }
                foreach (var (enPre, zhPre) in _modifierPrefixes)
                {
                    if (work.StartsWith(enPre, StringComparison.OrdinalIgnoreCase))
                    {
                        modsZh += zhPre;
                        work = work.Substring(enPre.Length).TrimStart();
                        matchedMod = true;
                        break;
                    }
                }
            }

            string calledZh = "";
            int namedIdx = work.IndexOf(" named ", StringComparison.OrdinalIgnoreCase);
            if (namedIdx > 0)
            {
                string nameVal = work.Substring(namedIdx + 7).Trim();
                if (ExactDict.TryGetValue(nameVal, out string trName)) nameVal = trName;
                calledZh = $"（真名：{nameVal}）";
                work = work.Substring(0, namedIdx).TrimEnd();
            }
            int calledIdx = work.IndexOf(" called ", StringComparison.OrdinalIgnoreCase);
            if (calledIdx > 0)
            {
                string callVal = work.Substring(calledIdx + 8).Trim();
                if (ExactDict.TryGetValue(callVal, out string trCall)) callVal = trCall;
                calledZh = $"（别名：{callVal}）" + calledZh;
                work = work.Substring(0, calledIdx).TrimEnd();
            }

            string baseZh = TranslateCoreBaseNoun(work);
            if (baseZh != work || !string.IsNullOrEmpty(modsZh) || !string.IsNullOrEmpty(trailingZh) || !string.IsNullOrEmpty(calledZh) || !string.IsNullOrEmpty(leadZh))
            {
                return $"{leadZh}{modsZh}{baseZh}{calledZh}{trailingZh}";
            }

            return phrase;
        }

        private static string TranslateCoreBaseNoun(string noun)
        {
            if (string.IsNullOrEmpty(noun)) return noun;
            if (ExactDict.TryGetValue(noun, out string hit)) return hit;

            if (noun.EndsWith("ies", StringComparison.OrdinalIgnoreCase) && noun.Length > 4)
            {
                string sing = noun.Substring(0, noun.Length - 3) + "y";
                if (ExactDict.TryGetValue(sing, out string sHit)) return sHit;
            }
            if (noun.EndsWith("staves", StringComparison.OrdinalIgnoreCase))
            {
                string sing = noun.Substring(0, noun.Length - 6) + "staff";
                if (ExactDict.TryGetValue(sing, out string sHit)) return sHit;
            }
            if (noun.EndsWith("knives", StringComparison.OrdinalIgnoreCase))
            {
                string sing = noun.Substring(0, noun.Length - 6) + "knife";
                if (ExactDict.TryGetValue(sing, out string sHit)) return sHit;
            }
            if (noun.EndsWith("es", StringComparison.OrdinalIgnoreCase) && noun.Length > 3)
            {
                string sing = noun.Substring(0, noun.Length - 2);
                if (ExactDict.TryGetValue(sing, out string sHit)) return sHit;
            }
            if (noun.EndsWith("s", StringComparison.OrdinalIgnoreCase) && noun.Length > 2)
            {
                string sing = noun.Substring(0, noun.Length - 1);
                if (ExactDict.TryGetValue(sing, out string sHit)) return sHit;
            }

            if (noun.EndsWith(" corpse", StringComparison.OrdinalIgnoreCase))
            {
                string mon = noun.Substring(0, noun.Length - 7).Trim();
                return TranslateCoreBaseNoun(mon) + "尸体";
            }
            if (noun.EndsWith(" corpses", StringComparison.OrdinalIgnoreCase))
            {
                string mon = noun.Substring(0, noun.Length - 8).Trim();
                return TranslateCoreBaseNoun(mon) + "尸体";
            }
            if (noun.StartsWith("statue of ", StringComparison.OrdinalIgnoreCase))
            {
                string mon = noun.Substring(10).Trim();
                return TranslateNounPhrase(mon) + "雕像";
            }
            if (noun.StartsWith("figurine of ", StringComparison.OrdinalIgnoreCase))
            {
                string mon = noun.Substring(12).Trim();
                return TranslateNounPhrase(mon) + "手办雕像";
            }
            if (noun.StartsWith("tin of ", StringComparison.OrdinalIgnoreCase) && noun.EndsWith(" meat", StringComparison.OrdinalIgnoreCase))
            {
                string mon = noun.Substring(7, noun.Length - 12).Trim();
                return TranslateCoreBaseNoun(mon) + "肉罐头";
            }
            if (noun.StartsWith("scroll labeled ", StringComparison.OrdinalIgnoreCase))
                return $"标有 {noun.Substring(15).Trim()} 的卷轴";
            if (noun.StartsWith("scrolls labeled ", StringComparison.OrdinalIgnoreCase))
                return $"标有 {noun.Substring(16).Trim()} 的卷轴";

            string[] containerPlurals = new string[] { "potions of ", "scrolls of ", "wands of ", "rings of ", "amulets of ", "spellbooks of " };
            string[] containerSingulars = new string[] { "potion of ", "scroll of ", "wand of ", "ring of ", "amulet of ", "spellbook of " };
            for (int i = 0; i < containerPlurals.Length; i++)
            {
                if (noun.StartsWith(containerPlurals[i], StringComparison.OrdinalIgnoreCase))
                {
                    string singForm = containerSingulars[i] + noun.Substring(containerPlurals[i].Length);
                    if (ExactDict.TryGetValue(singForm, out string pHit)) return pHit;
                }
            }

            int ofIdx = noun.IndexOf(" of ", StringComparison.OrdinalIgnoreCase);
            if (ofIdx > 0)
            {
                string basePart = noun.Substring(0, ofIdx).Trim();
                string ofPart = noun.Substring(ofIdx).Trim();
                if (ExactDict.TryGetValue(ofPart, out string ofZh))
                {
                    string baseTr = TranslateCoreBaseNoun(basePart);
                    return $"{ofZh}之{baseTr}";
                }
            }

            return noun;
        }
    }
}
